// Export/import of movements as a spreadsheet (Configuración → Tus datos). The format is Moni's own: export once to
// get a file with the right columns, edit it in Excel, and re-import it. Only Gasto/Ingreso rows come back in —
// everything else (transferencias, pagos compartidos, ajustes, saldo inicial) is informational on export only,
// since those are generated by the app itself and are not safe to recreate from a spreadsheet row.
import { formatAmountInput, parseAmountInput } from '@/shared/lib/amountInput'
import type { TransactionKind } from '@/shared/lib/database.types'
import { fromCents, type Cents } from '@/shared/lib/money'
import { isIsoDate, type IsoDate } from '@/shared/lib/month'
import type { EntryKind } from '@/features/transactions/domain/transaction'

export const MOVEMENT_SHEET_NAME = 'Movimientos'

export const MOVEMENT_COLUMNS = ['Fecha', 'Tipo', 'Monto', 'Categoría', 'Cuenta', 'Nota'] as const

/** Read-only labels for every kind the export can show. */
const KIND_LABELS: Record<TransactionKind, string> = {
  expense: 'Gasto',
  income: 'Ingreso',
  shared_payment: 'Pago compartido',
  settlement_out: 'Pago a un grupo',
  settlement_in: 'Cobro de un grupo',
  adjustment_in: 'Ajuste a favor',
  adjustment_out: 'Ajuste en contra',
  opening_in: 'Saldo inicial',
}

/** The only labels an imported row can turn back into a movement. */
const IMPORTABLE_KIND_BY_LABEL: Record<string, EntryKind> = {
  gasto: 'expense',
  ingreso: 'income',
}

export interface ExportableTransaction {
  kind: TransactionKind
  amountCents: Cents
  occurredOn: IsoDate
  categoryId: string | null
  accountId: string
  note: string | null
}

/** Rows ready to hand to a spreadsheet writer, header row included. */
export function buildMovementRows(
  transactions: readonly ExportableTransaction[],
  categoryNameById: ReadonlyMap<string, string>,
  accountNameById: ReadonlyMap<string, string>,
): (string | number)[][] {
  const rows = transactions.map((t) => [
    t.occurredOn,
    KIND_LABELS[t.kind] ?? t.kind,
    Number(fromCents(t.amountCents)),
    t.categoryId ? categoryNameById.get(t.categoryId) ?? '' : '',
    accountNameById.get(t.accountId) ?? '',
    t.note ?? '',
  ])
  return [[...MOVEMENT_COLUMNS], ...rows]
}

export interface ParsedMovementRow {
  /** 1-based, matching the row a person would see in Excel (header is row 1). */
  rowNumber: number
  kind: EntryKind
  amountCents: Cents
  occurredOn: IsoDate
  /** Never null: the database requires a category on every expense/income movement, so an unmatched
   * "Categoría" cell makes the row an issue instead (see `parseMovementRows`). */
  categoryId: string
  accountId: string
  note: string | null
}

export interface MovementImportIssue {
  rowNumber: number
  reason: string
}

export interface ParsedMovementsWorkbook {
  rows: ParsedMovementRow[]
  issues: MovementImportIssue[]
}

export interface MovementRowLookups {
  /** Key: `${kind}::${name.trim().toLowerCase()}`. */
  categoryIdByKindAndName: ReadonlyMap<string, string>
  /** Key: `name.trim().toLowerCase()`. */
  accountIdByName: ReadonlyMap<string, string>
  /** Used when the row's "Cuenta" cell is empty. */
  defaultAccountId: string | null
}

const EXCEL_EPOCH_MS = Date.UTC(1899, 11, 30)

function parseRowDate(value: unknown): IsoDate | null {
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null
    return value.toISOString().slice(0, 10)
  }
  if (typeof value === 'number' && Number.isFinite(value)) {
    const date = new Date(EXCEL_EPOCH_MS + Math.round(value * 86_400_000))
    if (Number.isNaN(date.getTime())) return null
    return date.toISOString().slice(0, 10)
  }
  if (typeof value === 'string') {
    const text = value.trim()
    if (isIsoDate(text)) return text
    const match = text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/)
    if (match && match[1] && match[2] && match[3]) {
      const [, day, month, year] = match
      const iso = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`
      if (isIsoDate(iso)) return iso
    }
  }
  return null
}

function parseRowAmount(value: unknown): Cents | null {
  if (typeof value === 'number' && Number.isFinite(value) && value !== 0) {
    return Math.round(Math.abs(value) * 100)
  }
  if (typeof value === 'string' && value.trim() !== '') {
    const cents = parseAmountInput(value.trim().replace(/^-/, ''))
    return cents === null || cents <= 0 ? null : cents
  }
  return null
}

function parseRowKind(value: unknown): EntryKind | null {
  if (typeof value !== 'string') return null
  return IMPORTABLE_KIND_BY_LABEL[value.trim().toLowerCase()] ?? null
}

function cellText(value: unknown): string {
  if (typeof value === 'string') return value.trim()
  if (typeof value === 'number') return formatAmountInput(Math.round(value * 100))
  return ''
}

const isBlankRow = (cells: readonly unknown[]) =>
  cells.every((cell) => cell === null || cell === undefined || cell === '')

/** Parses rows already split into cells (one array per spreadsheet row, header excluded). */
export function parseMovementRows(
  dataRows: readonly unknown[][],
  lookups: MovementRowLookups,
): ParsedMovementsWorkbook {
  const rows: ParsedMovementRow[] = []
  const issues: MovementImportIssue[] = []

  dataRows.forEach((cells, index) => {
    const rowNumber = index + 2
    if (isBlankRow(cells)) return
    const [fecha, tipo, monto, categoria, cuenta, nota] = cells

    const kind = parseRowKind(tipo)
    if (!kind) {
      issues.push({
        rowNumber,
        reason: `El tipo "${cellText(tipo) || '(vacío)'}" no se puede importar: solo Gasto o Ingreso.`,
      })
      return
    }

    const occurredOn = parseRowDate(fecha)
    if (!occurredOn) {
      issues.push({ rowNumber, reason: 'La fecha está vacía o no se entiende.' })
      return
    }

    const amountCents = parseRowAmount(monto)
    if (amountCents === null) {
      issues.push({ rowNumber, reason: 'El monto está vacío o no es un número válido.' })
      return
    }

    const accountName = cellText(cuenta)
    const accountId = accountName
      ? lookups.accountIdByName.get(accountName.toLowerCase()) ?? null
      : lookups.defaultAccountId
    if (!accountId) {
      issues.push({
        rowNumber,
        reason: accountName
          ? `No encontramos ninguna cuenta llamada "${accountName}".`
          : 'La cuenta está vacía y no hay una cuenta por defecto para asignar.',
      })
      return
    }

    const categoryName = cellText(categoria)
    const categoryId = categoryName
      ? lookups.categoryIdByKindAndName.get(`${kind}::${categoryName.toLowerCase()}`) ?? null
      : null
    if (!categoryId) {
      issues.push({
        rowNumber,
        reason: categoryName
          ? `No encontramos ninguna categoría de ${KIND_LABELS[kind].toLowerCase()} llamada "${categoryName}". Creala en Moni o corregí el nombre y volvé a intentar.`
          : 'Le falta la categoría, y un gasto o ingreso siempre necesita una.',
      })
      return
    }

    const note = cellText(nota) || null

    rows.push({ rowNumber, kind, amountCents, occurredOn, categoryId, accountId, note })
  })

  return { rows, issues }
}
